package com.bank.profile.model;

import jakarta.persistence.*;
import java.util.ArrayList;
import java.util.List;

@Entity
@Table(name = "customers")
public class Customer {

    @Id
    @Column(name = "customer_id")
    private String customerId;

    private String name;
    private String email;

    // ═══ @ElementCollection: List<String> phone numbers ═══
    @ElementCollection(fetch = FetchType.LAZY)
    @CollectionTable(name = "customer_phones",
        joinColumns = @JoinColumn(name = "customer_id"))
    @Column(name = "phone_number")
    @OrderColumn(name = "phone_order")
    private List<String> phoneNumbers = new ArrayList<>();
    // No @Entity for phone! No PhoneRepository! Just strings.
    // Stored in: customer_phones (customer_id, phone_number, phone_order)

    // ═══ @ElementCollection: List<Address> embeddable ═══
    @ElementCollection(fetch = FetchType.LAZY)
    @CollectionTable(name = "customer_addresses",
        joinColumns = @JoinColumn(name = "customer_id"))
    private List<Address> addresses = new ArrayList<>();
    // Address is @Embeddable — no @Id, no identity.
    // Stored in: customer_addresses (customer_id, line1, city, state, pincode)

    protected Customer() {}

    public Customer(String customerId, String name, String email) {
        this.customerId = customerId;
        this.name = name;
        this.email = email;
    }

    public String getCustomerId() { return customerId; }
    public String getName() { return name; }
    public List<String> getPhoneNumbers() { return phoneNumbers; }
    public List<Address> getAddresses() { return addresses; }
}
