// ─── File: src/main/java/com/bank/profile/service/CustomerProfileService.java ───
package com.bank.profile.service;

import com.bank.profile.dto.ProfileResponse;
import com.bank.profile.model.*;
import com.bank.profile.repository.CustomerRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
@Slf4j
public class CustomerProfileService {

    private final CustomerRepository customerRepo;

    @Transactional(readOnly = true)
    public ProfileResponse getProfile(String customerId) {
        Customer customer = customerRepo.findById(customerId)
            .orElseThrow(() -> new IllegalArgumentException("Not found: " + customerId));

        // Access LAZY collections — inside @Transactional, session is open
        var phones = customer.getPhoneNumbers();
        var addresses = customer.getAddresses().stream()
            .map(a -> a.line1() + ", " + a.city() + " " + a.pincode())
            .toList();

        return new ProfileResponse(customerId, customer.getName(), phones, addresses);
    }

    @Transactional
    public void addPhone(String customerId, String phone) {
        Customer customer = customerRepo.findById(customerId).orElseThrow();
        customer.getPhoneNumbers().add(phone);

        // At flush: DELETE ALL phones for this customer, then REINSERT all!
        // SQL: DELETE FROM customer_phones WHERE customer_id = 'CUST-001'
        //      INSERT INTO customer_phones VALUES ('CUST-001', '+91-9876543210', 0)
        //      INSERT INTO customer_phones VALUES ('CUST-001', '+91-9876543211', 1)
        //      INSERT INTO customer_phones VALUES ('CUST-001', '+91-NEW', 2)
        log.warn("(Caution) Adding 1 phone triggers DELETE-ALL + REINSERT-ALL for this customer's phones!");
    }

    @Transactional
    public void addAddress(String customerId, Address address) {
        Customer customer = customerRepo.findById(customerId).orElseThrow();
        customer.getAddresses().add(address);
        // Same delete-all + reinsert behavior for addresses
    }
}
```

