    private final CustomerProfileService service;

    @GetMapping("/{customerId}")
    public ProfileResponse profile(@PathVariable String customerId) {
        return service.getProfile(customerId);
    }

    @PostMapping("/{customerId}/phone")
    public String addPhone(@PathVariable String customerId, @RequestParam String phone) {
        service.addPhone(customerId, phone);
        return "Phone added (delete-all + reinsert triggered!)";
    }
}
