// ─── File: src/test/java/com/bank/profile/service/ElementCollectionTest.java ───
package com.bank.profile.service;

import com.bank.profile.model.*;
import org.junit.jupiter.api.Test;
import java.util.List;
import static org.assertj.core.api.Assertions.*;

class ElementCollectionTest {

    @Test
    void addressIsEmbeddableNoIdentity() {
        Address a1 = new Address("42 MG Road", "Mumbai", "Maharashtra", "400001");
        Address a2 = new Address("42 MG Road", "Mumbai", "Maharashtra", "400001");
        assertThat(a1).isEqualTo(a2);  // record equals — value comparison
        // Address has no @Id — it IS its values. Two identical addresses are EQUAL.
    }

    @Test
    void phoneNumbersAreBasicValues() {
        Customer customer = new Customer("C1", "Rajesh", "r@bank.com");
        customer.getPhoneNumbers().add("+91-9876543210");
        customer.getPhoneNumbers().add("+91-9876543211");
        assertThat(customer.getPhoneNumbers()).hasSize(2);
        // Just strings! No Phone entity, no PhoneRepository.
    }

    @Test
    void elementCollectionVsOneToMany() {
        // @ElementCollection:
        //   (Recommended) Small lists (2-3 phones, 1-2 addresses)
        //   (Recommended) No identity needed (just values)
        //   (Recommended) No separate @Entity/@Repository
        //   (Avoid) DELETE-ALL + REINSERT on any change
        //   (Avoid) Bad for large collections

        // @OneToMany:
        //   (Recommended) Large collections (thousands of trades)
        //   (Recommended) Individual elements have @Id → targeted UPDATE/DELETE
        //   (Recommended) Independent queries, cascading, versioning
        //   (Avoid) Requires separate @Entity, @Id, Repository

        assertThat(true).isTrue();
    }
}
